package com.kitchensink.member.dto;

import com.kitchensink.member.model.Role;
import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotNull;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/** Admin "add member": profile plus the role to grant. The password is generated by the server. */
@Getter
@Setter
@NoArgsConstructor
public class CreateMemberRequest extends MemberProfileRequest {

    @Schema(example = "VIEWER")
    @NotNull(message = "Choose a role")
    private Role role;
}
